) AS (
  VALUES 
    (174::BIGINT, 'Deja muchos trabajos para un curso de 0 créditos y pone películas muy aburridas. Se pasa fácil, pero no debería exigir dedicar tanto tiempo extra para una cultural.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '398fc2cf66334972e9631a8aff114c2cce725f458dfe804fc1fe5a1f8feb17f7'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'Los que ponen que las películas son aburridas y con "cierto sesgo ideológico" (como si todo no tuviera sesgo ideológico) lo único que hacen es demostrar su enorme ignorancia jaja el curso está bien, pero sí pesado por los trabajos'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-09-11T00:00:00+00:00'::TIMESTAMPTZ, 'f8295b59a9ee14a15aa3b971a7f8ed6ca68a81f65a0fdc5f0a331f640b3a7a52'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'No es difícil pasar, es muy entretenido pero deja muchas cosas qué hacer que consumen demasiado tiempo como para ser una cultural, preferiría matricular otras culturales que esta por las tareas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2025-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ed8837eeee1652ca6379bac174e56060745bae9949968483da2bd81b4ef15337'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'Deja muchas tareas para un curso de 0 créditos, que realmente no son la gran cosa pero ahí están. Explica con videos, las películas que pone son muy aburridas y tendrá que exponerla según cuál grupo sea usted. Al final de curso tiene que hacer un video corto con lo "aprendido"'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2024-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'ad4f7b364ed586bddea665ccde27b06b653d5e1164f20339b03a34b5d0163606'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'Deja muchos trabajos para un curso de 0 créditos, pone películas aburridas en su mayoría y con cierto sesgo ideológico, la profe explica bien, pero no vale la pena y al final deja un proyecto de grabar un video'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-05-28T00:00:00+00:00'::TIMESTAMPTZ, '7de50e15512e78d855b600d65fd183d52de4d0a15685ca2ef7ba3d3c298a7b30'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'un curso de 0 créditos con demasiadas tareas, las películas muy aburridas. cree que el curso vale como 4 créditos. Y a veces se contradice con ella misma'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2023-08-21T00:00:00+00:00'::TIMESTAMPTZ, '80448ba8a4f3637cdfe322c73b94c80c35d779a1dce2bdfac9bccd31bc4527ea'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'Un curso de 0 créditos lleno de tareas, la profe es muy estricta en tema de asistencias y en tareas, si se le acumula el trabajo no rinde bien, las películas que escogió en mi opinión fueron demasiado aburridas, no explica nada todo es puro video, no la recomiendo'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '5b3b0dcfdb311803f1add96b855e46f1e86f19e493549baf173db391c0fc95df'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'La profe cambió el plan de estudio en la última semana. Reviso el guion para el proyecto final dos días antes, y también dio materia dos días antes de poder grabar el proyecto final. La clase entera tenía entendida una indicación la cual cambió a última hora y tachó toda la clase de mentirosos.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, '460fc11e297f1ce20f7ec3ee314c9df1583e9adba2e5773f520724cc86d40b1d'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'No matriculen apreciación de cine es demasiado trabajo extra clase'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'a2959917759c77ad432ae06847ed4c25f10a1c7e74efae4bf4a7243ea379f241'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-09-15T00:00:00+00:00'::TIMESTAMPTZ, 'ec95a1bd5bd181bdd249838316c1389f7fd4b846c5854750e99156d0da288646'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'Las clases son vacilonas y largas. Los trabajos cuando deja son un poco larguillos, las peliculas que ella elige son buenas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '8fc46f45b949d9ebd2c6f4f14f71c3462d33fc55113f143daa96dd90122363a8'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'Excelente docente. No se aburrirán ni un momento con el catálogo de películas. Se nota que la profesora sabe mucho y que le gusta mucho dar clases. La participación y la asistencia son súper importantes, pero el curso es increiblemente entretenido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2021-06-28T00:00:00+00:00'::TIMESTAMPTZ, '6ac90159388be2e53299fec5b51d6d005cde6a6060f8bf6bf2666d171bf0de3f'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'Muy buena curso!! La profe explica muy bien la materia; es experta en el tema :) La participación y el trabajo grupal son importantes en la clase. Va a aprender la técnica y la magia del cine desde los planos hasta movimientos de camara y tipos de sonido. 100% recomendada!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'afde7a313cde0a2cd0086afe1af6a2393bf051d224d1563c27982beeb356145b'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'Muy buena persona y profesora, no es difícil de pasar si presenta todos los trabajos que deja, que son trabajos fáciles y muy entretenidos. Muy recomendado si desea olvidarse del resto de cursos por un momento.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '8e2170cc818b05a9406fe6efe10d3f59b1ca5ec94df125c8ac73525a8a41688a'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'Muy muy buena profe, se preocupa por el estudiante y su salud mental, la clase es muy entretenida y los trabajos que se hacen en esta nueva modalidad virtual también son muy entretenidos, totalmente recomendada para Artes Visuales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '1249f00fed89ffd292b7d6574f93b033ac94d59a3bf15d456abfe80c53901f47'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'Es super buena persona y profe, se preocupa por la salud mental de uno y de que uno no tenga colapsos. La única cosa es que sentí que dejaba muchos trabajos para un curso de 0 créditos, pero igual eran fáciles. Si son como yo y son malos en artes, no se preocupen, no se van a quedar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'c6c26f282c9a845033457c38394c28640eed99fdfb31413e8e5c88d7ef865a3e'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'La profe es buena la cosa esque deja DEMASIADO trabajo para ser un curso de 0 créditos deja al final del curso un video que no es difícil pero si su horario no es flexible y el de los compañeros tampoco cuesta hacerlo y más si los compañeros son unos vagos, algunas películas son un bostezo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-28T00:00:00+00:00'::TIMESTAMPTZ, '8a441f57b31757130016b8d31a1f48bca8693554db6eb7876b0edfb649825330'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'A veces es grosera, pero la clase en general es fácil y entretenida. Evite faltar y vaya haciendo todo al día. Lo único fuera de clase es ir al Art City Tour pero es vacilón.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-08-18T00:00:00+00:00'::TIMESTAMPTZ, '77f2060d8b30e9b4b83f67ecbe487921b84b7514e931be841fdef51346132ffe'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'Ella es una artista y explica muy bien las clases. Para evitar problemas es mejor seguir las intrucciones y suprimir cualquier comentario pues es liberal y de mente cerrada. Sin embargo, es profesional en su trabajo y hace la clase agradable.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '41b982f68769a75f0e7a9242c13e19ecfce99c39ca3d0066ce9ea65a64a63524'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'En sí, ella a veces es pesada, pero es buena persona. Con respecto al curso, es súper llevadero y calmado, todo se hace durante tiempo de clases. La única tarea es un reporte del Art City Tour, pero es bonito. Los proyectos son fáciles. Califica extraño, pero es casi que imposible perder el curso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '979d003d068622fbea87157356bb16364401cb1425a0cea74d65c875787ebe28'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'Odiosa y aveces responde muy sarcásticamente pero la clase es fácil y entretenida'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, '3600c052c6147d1ccdf52e9f7df8ba575ca2f6204e257f38fe577af10e8547a4'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'La clase es divertida. Se hacen varios proyectos que requieren tiempo y esfuerzo. La única tarea que deja es un reporte del Art City Tour, pero realmente es interesante ver a San José desde esa perspectiva al menos una noche. Fue interesante la verdad, si puede llévelo con ella :D'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '6e7611fe5eb64c6d665c3bc482f89bbdd471b038eb807ffcdbe64e7564e5dc29'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-05-20T00:00:00+00:00'::TIMESTAMPTZ, 'b77671ae6e47efae45a9adaad2377534d3127777546d00ed1e606ff5957e8eca'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'bc820106a69658549193c6bdf358f91c61648b5cb68715ba7a7abe2963e98aae'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'Clases divertidas, un espacio para salir de la rutina y hacer nuevos amigos. Solo se hace un trabajo de una hoja máximo sobre el art city tour.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'ea48ecf6e6dca0b2bdbb0953d9d86006cd7f8736ee3f24a02f9b6f0dd4e8dde1'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'La profe es pura vida, es una clase para desestresarse un rato; la única tarea que deja es un reporte del art city tour. Super recomendada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-15T00:00:00+00:00'::TIMESTAMPTZ, '7456370442e142b9978bc1fa5d508bd8087e59c45b675d6bbad89078a40af548'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'Gg izi.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-08T00:00:00+00:00'::TIMESTAMPTZ, 'a6e19a5d47b4a8fc0c7d8507a2f991d7e8bdeca81c2410de98f8ac88f903659a'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'Un curso para ir a distraerse un rato y salir de la rutina. Solo se debe hacer un reporte de una hoja sobre el art city tour. Tomaría su clase todos los semestres si pudiera'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'cb38560af053d8af921d47dfe175bcea46e408750ed4c20cbae20f33f8a4174b'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'Se preocupa por hacer una clase sumamente entretenida y amena. Ella es muy alegre y buena nota. Excelente profesora!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f42b855257a3956fff10e55361245d8313a9482cc0fd8d2c3cf0e2ca5926ea41'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'Hace todo lo posible para que la clase sea entretenida y lo logra.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-30T00:00:00+00:00'::TIMESTAMPTZ, '5fe137ead4cdff53bb27e1b373d3d0621f54eb6d7cb3d0da7d5578aaf9182060'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e91d65df774a0316319f1889e0038d087f1ad96709fcb408146bd7f5c776e1df'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'Curso ameno e interesante. Persona exageradamente sarcástica pero buena nota y comprensiva.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-27T00:00:00+00:00'::TIMESTAMPTZ, '83f11afc89b1ad1384a7e372e703d31496536f39e14d40b5d3bafa2d8b09d9a8'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'Con ir a clases basta para pasar el curso, algunas películas son buenas otras algo raras. Si se recomienda.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, '8e0895da1d4d512c43de66507dff33d0c00305c4423623870f3fbd0c3b2d6fbe'::TEXT, ARRAY[504]::BIGINT[]),
    (174::BIGINT, 'Excelente profe! Super chiva, tiene su manera de trato, algo sarcastica, pero hay que saber tomar el lado positivo y es muy chiva todo con ella'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'd992cf9dec2a1218ffaddc64809a433be9381918753210a47ec360d5a47138cc'::TEXT, ARRAY[501]::BIGINT[]),
    (174::BIGINT, 'Es una profesora odiosa, prepotente, contesta de manera agresiva con un tono sarcástico, el curso es sencillo, te hace ir a una actividad en la noche a San José que vale 14%. El curso podría ser más bonito, no le gusta pintar, se hace una "escultura" de Arcilla'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-05T00:00:00+00:00'::TIMESTAMPTZ, '2d54b58e00cbcb5b96b1689cc0416c0fa4f727b0df41a30284fbdcca3304b8a9'::TEXT, ARRAY[501]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
